using System;using System.IO;using System.Diagnostics;using System.Threading;
class Harness {
 static Process Start(string file,string args){return Process.Start(new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,file),args){UseShellExecute=false,RedirectStandardError=true,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
 static int Main(){try{string marker=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"restarted.txt");foreach(string mode in new[]{"normal","admin","authorized"}){if(File.Exists(marker))File.Delete(marker);string key=Guid.NewGuid().ToString("N"),stopName="Local\\Test.Stop."+key,adminName="Local\\Test.Admin."+key;using(var stop=new EventWaitHandle(false,EventResetMode.ManualReset,stopName))using(var admin=new EventWaitHandle(mode=="admin",EventResetMode.ManualReset,adminName))using(var child=Start("GameZoneyCliente.exe","hold")){using(var guard=Start("GameZoneyMonitor.exe",child.Id+" "+child.StartTime.ToUniversalTime().Ticks+" "+stopName+" "+adminName+" 2")){Thread.Sleep(700);if(mode=="authorized")stop.Set();child.Kill();child.WaitForExit();if(!guard.WaitForExit(12000)){guard.Kill();throw new Exception("Monitor travou");}if(guard.ExitCode!=0)throw new Exception("Falha do monitor "+mode+" "+guard.StandardError.ReadToEnd());Thread.Sleep(600);if(File.Exists(marker)!=(mode=="normal"))throw new Exception("Reinicio incorreto "+mode);Console.WriteLine("PASS "+mode);}}}return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
